// Main Component
const CriminalJusticeBranching: React.FC<CriminalJusticeBranchingProps> = ({
  backgroundColor = "#030712",
  transparentBackground = false,
  durationInSeconds = 10,
  circleColor = "#111827",
  lineColorStart = "#38bdf8",
  lineColorEnd = "#818cf8",
  card1Title = "It affects",
  card1Highlight = "probation",
  card1Color = "#3b82f6",
  card2Title = "It affects",
  card2Highlight = "Parole",
  card2Color = "#0d9488",
  card3Title = "It affects",
  card3Highlight = "how much time they serve",
  card3Color = "#8b5cf6",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const finalBgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Timings & Progress Variables
  const circleScaleSpring = spring({
    frame,
    fps,
    config: { damping: 13, mass: 0.9 },
  });

  // Headlight activation starts at frame 30, peaks at 48
  const headlightGlow = interpolate(frame, [30, 48], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Animated background glowing particles (seeded deterministically)
  const particles = Array.from({ length: 18 }).map((_, index) => {
    const seed = index * 142.34;
    const initialX = random(seed + "x") * width;
    const initialY = random(seed + "y") * height;
    const size = random(seed + "size") * 4 + 2;
    const driftY = interpolate(frame, [0, 300], [0, -50 * (random(seed + "drift") + 0.5)]);
    const opacity = interpolate(
      Math.sin((frame + seed) * 0.05),
      [-1, 1],
      [0.1, 0.4]
    );

    return {
      x: initialX,
      y: (initialY + driftY + height) % height,
      size,
      opacity,
    };
  });

  // Layout Measurements relative to Width & Height
  const cx = width * 0.22;
  const cy = height * 0.5;
  const cr = Math.min(width, height) * 0.17; // Circle Radius

  const startX = cx + cr;
  const startY = cy;

  const cardX = width * 0.44;
  const card1Y = height * 0.26;
  const card2Y = height * 0.5;
  const card3Y = height * 0.74;

  const dx = (cardX - startX) * 0.5;

  // Staggered Line Animation Parameters
  const progressMid = interpolate(frame, [42, 70], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const progressTop = interpolate(frame, [45, 75], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const progressBot = interpolate(frame, [48, 80], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Path SVG definitions
  const dMid = `M ${startX} ${startY} L ${cardX} ${card2Y}`;
  const dTop = `M ${startX} ${startY} C ${startX + dx} ${startY}, ${startX + dx} ${card1Y}, ${cardX} ${card1Y}`;
  const dBot = `M ${startX} ${startY} C ${startX + dx} ${startY}, ${startX + dx} ${card3Y}, ${cardX} ${card3Y}`;

  // Approximate lengths for Dash offset animation
  const lenMid = cardX - startX;
  const lenTop = Math.sqrt((cardX - startX) ** 2 + (card1Y - startY) ** 2) * 1.15;
  const lenBot = Math.sqrt((cardX - startX) ** 2 + (card3Y - startY) ** 2) * 1.15;

  // Cards Reveal Animations (Starts right as line drawings hit endpoint)
  const card1Spring = spring({
    frame: frame - 72,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const card2Spring = spring({
    frame: frame - 67,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const card3Spring = spring({
    frame: frame - 77,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  // Floating ambient cycle of the main circle
  const ambientCirclePulse = Math.sin(frame * 0.04) * 3;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: interFamily,
        overflow: "hidden",
        backgroundImage: `radial-gradient(circle at 25% 50%, #1e293b55 0%, #030712 100%)`,
        transition: "none",
      }}
    >
      {/* Background Particles */}
      {particles.map((p, idx) => (
        <div
          key={idx}
          style={{
            position: "absolute",
            left: p.x,
            top: p.y,
            width: p.size,
            height: p.size,
            borderRadius: "50%",
            backgroundColor: "#38bdf8",
            opacity: p.opacity,
            pointerEvents: "none",
            boxShadow: "0 0 8px rgba(56, 189, 248, 0.5)",
            transition: "none",
          }}
        />
      ))}

      {/* SVG Connecting Paths Overlay */}
      <svg
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: "100%",
          pointerEvents: "none",
          overflow: "visible",
          transition: "none",
        }}
      >
        <defs>
          {/* Main glowing line gradient */}
          <linearGradient id="lineGrad" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor={lineColorStart} />
            <stop offset="100%" stopColor={lineColorEnd} />
          </linearGradient>

          {/* Line Blur Filter for Bloom Effect */}
          <filter id="bloom" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="6" result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>

        {/* --- Top Connecting Line --- */}
        {progressTop > 0 && (
          <>
            {/* Soft background glow trace */}
            <path
              d={dTop}
              fill="none"
              stroke={lineColorStart}
              strokeWidth="6"
              strokeLinecap="round"
              strokeDasharray={lenTop}
              strokeDashoffset={lenTop * (1 - progressTop)}
              opacity="0.3"
              filter="url(#bloom)"
            />
            {/* High-intensity solid foreground core */}
            <path
              d={dTop}
              fill="none"
              stroke="url(#lineGrad)"
              strokeWidth="3.5"
              strokeLinecap="round"
              strokeDasharray={lenTop}
              strokeDashoffset={lenTop * (1 - progressTop)}
            />
          </>
        )}

        {/* --- Middle Connecting Line --- */}
        {progressMid > 0 && (
          <>
            <path
              d={dMid}
              fill="none"
              stroke={lineColorStart}
              strokeWidth="6"
              strokeLinecap="round"
              strokeDasharray={lenMid}
              strokeDashoffset={lenMid * (1 - progressMid)}
              opacity="0.3"
              filter="url(#bloom)"
            />
            <path
              d={dMid}
              fill="none"
              stroke="url(#lineGrad)"
              strokeWidth="3.5"
              strokeLinecap="round"
              strokeDasharray={lenMid}
              strokeDashoffset={lenMid * (1 - progressMid)}
            />
          </>
        )}

        {/* --- Bottom Connecting Line --- */}
        {progressBot > 0 && (
          <>
            <path
              d={dBot}
              fill="none"
              stroke={lineColorStart}
              strokeWidth="6"
              strokeLinecap="round"
              strokeDasharray={lenBot}
              strokeDashoffset={lenBot * (1 - progressBot)}
              opacity="0.3"
              filter="url(#bloom)"
            />
            <path
              d={dBot}
              fill="none"
              stroke="url(#lineGrad)"
              strokeWidth="3.5"
              strokeLinecap="round"
              strokeDasharray={lenBot}
              strokeDashoffset={lenBot * (1 - progressBot)}
            />
          </>
        )}

        {/* Connecting Dot: Center Starting Trigger */}
        {circleScaleSpring > 0.1 && (
          <circle
            cx={startX}
            cy={startY}
            r={interpolate(frame, [38, 48], [0, 6], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            })}
            fill={lineColorStart}
            filter="url(#bloom)"
          />
        )}

        {/* Connecting End Dots on arrival */}
        {progressTop >= 0.95 && (
          <circle
            cx={cardX}
            cy={card1Y}
            r="5"
            fill={lineColorEnd}
            filter="url(#bloom)"
          />
        )}
        {progressMid >= 0.95 && (
          <circle
            cx={cardX}
            cy={card2Y}
            r="5"
            fill={lineColorEnd}
            filter="url(#bloom)"
          />
        )}
        {progressBot >= 0.95 && (
          <circle
            cx={cardX}
            cy={card3Y}
            r="5"
            fill={lineColorEnd}
            filter="url(#bloom)"
          />
        )}
      </svg>

      {/* LEFT ASPECT: GLO-CONTAINER FOR CENTRAL GRAPHIC */}
      <div
        style={{
          position: "absolute",
          left: cx - cr,
          top: cy - cr + ambientCirclePulse,
          width: cr * 2,
          height: cr * 2,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${circleScaleSpring})`,
          transformOrigin: "center center",
          transition: "none",
        }}
      >
        {/* Outer Circular Neon Blue Glow Border */}
        <div
          style={{
            position: "absolute",
            width: "100%",
            height: "100%",
            borderRadius: "50%",
            border: "3px solid #38bdf8",
            boxShadow: `0 0 20px rgba(56, 189, 248, 0.6), inset 0 0 15px rgba(56, 189, 248, 0.4)`,
            opacity: 0.9,
            transition: "none",
          }}
        />

        {/* Second layered thin circular ring with dashed style */}
        <div
          style={{
            position: "absolute",
            width: "92%",
            height: "92%",
            borderRadius: "50%",
            border: "1px dashed #818cf8",
            opacity: 0.5,
            transform: `rotate(${frame * 0.4}deg)`,
            transition: "none",
          }}
        />

        {/* Rich Glass Center of Graphic Circle */}
        <div
          style={{
            position: "absolute",
            width: "84%",
            height: "84%",
            backgroundColor: circleColor,
            borderRadius: "50%",
            overflow: "hidden",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            boxShadow: "0 10px 30px rgba(0, 0, 0, 0.5)",
            border: "1px solid rgba(255, 255, 255, 0.08)",
            transition: "none",
          }}
        >
          {/* Internal graphics layer */}
          <div
            style={{
              width: "80%",
              height: "80%",
              transform: `scale(${interpolate(frame, [15, 45], [0.8, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              })})`,
              opacity: interpolate(frame, [15, 35], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }),
              transition: "none",
            }}
          >
            <CarIcon headlightGlow={headlightGlow} />
          </div>
        </div>
      </div>

      {/* RIGHT ASPECT: VERTICALLY STACKED GLASS CARDS */}
      <div
        style={{
          position: "absolute",
          left: cardX + width * 0.02,
          top: 0,
          width: width * 0.46,
          height: "100%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          gap: `${height * 0.04}px`,
          pointerEvents: "none",
          transition: "none",
        }}
      >
        {/* CARD 1 (Top) */}
        <div
          style={{
            height: `${height * 0.19}px`,
            borderRadius: Math.min(width, height) * 0.02,
            background: "rgba(10, 17, 32, 0.5)",
            backdropFilter: "blur(16px)",
            border: "1px solid rgba(255, 255, 255, 0.07)",
            padding: `${height * 0.015}px ${width * 0.025}px`,
            display: "flex",
            alignItems: "center",
            boxShadow: `0 12px 32px rgba(0, 0, 0, 0.5), inset 0 0 0 1px rgba(59, 130, 246, 0.15)`,
            opacity: card1Spring,
            transform: `scale(${card1Spring}) translateX(${(1 - card1Spring) * 60}px)`,
            transformOrigin: "left center",
            transition: "none",
          }}
        >
          {/* Card Icon Space */}
          <div
            style={{
              width: Math.min(width, height) * 0.11,
              height: Math.min(width, height) * 0.11,
              flexShrink: 0,
              backgroundColor: "rgba(59, 130, 246, 0.08)",
              borderRadius: "16%",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              marginRight: `${width * 0.025}px`,
              border: "1px solid rgba(59, 130, 246, 0.25)",
              transform: `scale(${interpolate(card1Spring, [0, 1], [0.7, 1])})`,
              transition: "none",
            }}
          >
            <ProbationIcon color={card1Color} />
          </div>

          {/* Card Typography Space */}
          <div style={{ display: "flex", flexDirection: "column", transition: "none" }}>
            <span
              style={{
                fontFamily: interFamily,
                color: "#94a3b8",
                fontSize: `${Math.min(width, height) * 0.03}px`,
                fontWeight: 500,
                letterSpacing: "0.5px",
                lineHeight: 1.2,
                transition: "none",
              }}
            >
              {card1Title}
            </span>
            <span
              style={{
                fontFamily: montserratFamily,
                color: card1Color,
                fontSize: `${Math.min(width, height) * 0.042}px`,
                fontWeight: 900,
                lineHeight: 1.25,
                marginTop: "2px",
                textShadow: `0 0 10px rgba(59, 130, 246, 0.3)`,
                transition: "none",
              }}
            >
              {card1Highlight}
            </span>
          </div>
        </div>

        {/* CARD 2 (Middle) */}
        <div
          style={{
            height: `${height * 0.19}px`,
            borderRadius: Math.min(width, height) * 0.02,
            background: "rgba(10, 17, 32, 0.5)",
            backdropFilter: "blur(16px)",
            border: "1px solid rgba(255, 255, 255, 0.07)",
            padding: `${height * 0.015}px ${width * 0.025}px`,
            display: "flex",
            alignItems: "center",
            boxShadow: `0 12px 32px rgba(0, 0, 0, 0.5), inset 0 0 0 1px rgba(13, 148, 136, 0.15)`,
            opacity: card2Spring,
            transform: `scale(${card2Spring}) translateX(${(1 - card2Spring) * 60}px)`,
            transformOrigin: "left center",
            transition: "none",
          }}
        >
          <div
            style={{
              width: Math.min(width, height) * 0.11,
              height: Math.min(width, height) * 0.11,
              flexShrink: 0,
              backgroundColor: "rgba(13, 148, 136, 0.08)",
              borderRadius: "16%",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              marginRight: `${width * 0.025}px`,
              border: "1px solid rgba(13, 148, 136, 0.25)",
              transform: `scale(${interpolate(card2Spring, [0, 1], [0.7, 1])})`,
              transition: "none",
            }}
          >
            <ParoleIcon color={card2Color} />
          </div>

          <div style={{ display: "flex", flexDirection: "column", transition: "none" }}>
            <span
              style={{
                fontFamily: interFamily,
                color: "#94a3b8",
                fontSize: `${Math.min(width, height) * 0.03}px`,
                fontWeight: 500,
                letterSpacing: "0.5px",
                lineHeight: 1.2,
                transition: "none",
              }}
            >
              {card2Title}
            </span>
            <span
              style={{
                fontFamily: montserratFamily,
                color: card2Color,
                fontSize: `${Math.min(width, height) * 0.042}px`,
                fontWeight: 900,
                lineHeight: 1.25,
                marginTop: "2px",
                textShadow: `0 0 10px rgba(13, 148, 136, 0.3)`,
                transition: "none",
              }}
            >
              {card2Highlight}
            </span>
          </div>
        </div>

        {/* CARD 3 (Bottom) */}
        <div
          style={{
            height: `${height * 0.19}px`,
            borderRadius: Math.min(width, height) * 0.02,
            background: "rgba(10, 17, 32, 0.5)",
            backdropFilter: "blur(16px)",
            border: "1px solid rgba(255, 255, 255, 0.07)",
            padding: `${height * 0.015}px ${width * 0.025}px`,
            display: "flex",
            alignItems: "center",
            boxShadow: `0 12px 32px rgba(0, 0, 0, 0.5), inset 0 0 0 1px rgba(139, 92, 246, 0.15)`,
            opacity: card3Spring,
            transform: `scale(${card3Spring}) translateX(${(1 - card3Spring) * 60}px)`,
            transformOrigin: "left center",
            transition: "none",
          }}
        >
          <div
            style={{
              width: Math.min(width, height) * 0.11,
              height: Math.min(width, height) * 0.11,
              flexShrink: 0,
              backgroundColor: "rgba(139, 92, 246, 0.08)",
              borderRadius: "16%",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              marginRight: `${width * 0.025}px`,
              border: "1px solid rgba(139, 92, 246, 0.25)",
              transform: `scale(${interpolate(card3Spring, [0, 1], [0.7, 1])})`,
              transition: "none",
            }}
          >
            <TimeServedIcon color={card3Color} frame={frame} />
          </div>

          <div
            style={{
              display: "flex",
              flexDirection: "column",
              maxWidth: width * 0.26,
              transition: "none",
            }}
          >
            <span
              style={{
                fontFamily: interFamily,
                color: "#94a3b8",
                fontSize: `${Math.min(width, height) * 0.03}px`,
                fontWeight: 500,
                letterSpacing: "0.5px",
                lineHeight: 1.2,
                transition: "none",
              }}
            >
              {card3Title}
            </span>
            <span
              style={{
                fontFamily: montserratFamily,
                color: card3Color,
                fontSize: `${Math.min(width, height) * 0.038}px`,
                fontWeight: 900,
                lineHeight: 1.2,
                marginTop: "2px",
                textShadow: `0 0 10px rgba(139, 92, 246, 0.3)`,
                transition: "none",
              }}
            >
              {card3Highlight}
            </span>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CriminalJusticeBranching;